css:
.dcx{margin:0;padding:0;background:#FFFFFF;font-family:'Plus Jakarta Sans',system-ui,sans-serif;color:#06171D;-webkit-font-smoothing:antialiased;overflow-x:clip}
.dcx a{color:#07784C;text-decoration:none}
.dcx a:hover{color:#053F2B}
.dcx h1,.dcx h2,.dcx h3,.dcx p{margin:0}
.dcx *:focus-visible{outline:2px solid #02B07A;outline-offset:2px}
.dcx :focus:not(:focus-visible){outline:none}
.dcx .nx-rail::-webkit-scrollbar{height:6px}
.dcx .nx-hide-sb::-webkit-scrollbar{display:none}
.dcx .nx-rail::-webkit-scrollbar-thumb{background:rgba(7,120,76,.35);border-radius:6px}
@keyframes nxOvIn{from{opacity:0}to{opacity:1}}
@keyframes nxDlgIn{from{opacity:0;transform:translateY(10px) scale(.985)}to{opacity:1;transform:none}}
@keyframes nxSheetIn{from{opacity:0;transform:translateY(24px)}to{opacity:1;transform:none}}
@keyframes nxPulse{0%,100%{transform:scale(1)}50%{transform:scale(1.07)}}
.dcx .nx-arr{display:inline-flex;transition:transform .16s ease-out}
.dcx .nx-cta:hover .nx-arr,.dcx .nx-ind:hover .nx-arr{transform:translateX(3px)}
.dcx .nx-btn{transition:transform .16s ease-out,box-shadow .16s ease-out,background .16s,color .16s}
.dcx .nx-btn:hover{transform:translateY(-1px);box-shadow:0 8px 18px -10px rgba(7,120,76,.45)}
.dcx .nx-ind-img{transition:transform .18s ease-out}
@media (hover:hover){.dcx .nx-ind:hover .nx-ind-img{transform:scale(1.01)}
}
html.nx-js .dcx [data-reveal]{transition:opacity .45s ease-out,transform .45s ease-out}
html.nx-js .dcx [data-reveal]:not([data-in]){opacity:0;transform:translateY(12px)}
.dcx .nx-gauge-bg{fill:none;stroke:#DDEFE6;stroke-width:10}
.dcx .nx-gauge{fill:none;stroke:#02B07A;stroke-width:10;stroke-linecap:round;stroke-dasharray:326.73;stroke-dashoffset:71.88;transition:stroke-dashoffset .75s ease-out .15s}
html.nx-js .dcx [data-reveal]:not([data-in]) .nx-gauge{stroke-dashoffset:326.73}
.dcx .nx-bar{transform-origin:left center;transition:transform .6s ease-out}
html.nx-js .dcx [data-reveal]:not([data-in]) .nx-bar{transform:scaleX(0)}
.dcx .nx-barv{transform-origin:center bottom;transition:transform .6s ease-out}
html.nx-js .dcx [data-reveal]:not([data-in]) .nx-barv{transform:scaleY(0)}
.dcx .nx-fade{transition:opacity .4s ease-out}
html.nx-js .dcx [data-reveal]:not([data-in]) .nx-fade{opacity:0}
@keyframes nxTabIn{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion: reduce){.dcx *{transition-duration:.01ms !important;animation-duration:.01ms !important}
html.nx-js .dcx [data-reveal]:not([data-in]){opacity:1;transform:none}
html.nx-js .dcx [data-reveal]:not([data-in]) .nx-gauge{stroke-dashoffset:71.88}
html.nx-js .dcx [data-reveal]:not([data-in]) .nx-bar,html.nx-js .dcx [data-reveal]:not([data-in]) .nx-barv{transform:none}
html.nx-js .dcx [data-reveal]:not([data-in]) .nx-fade{opacity:1}
.dcx .nx-btn:hover{transform:none}
}
